package com.backend.movie.entities

import org.springframework.data.annotation.CreatedDate
import org.springframework.data.annotation.Id
import org.springframework.data.annotation.LastModifiedDate
import org.springframework.data.annotation.Version
import org.springframework.data.relational.core.mapping.InsertOnlyProperty
import org.springframework.data.relational.core.mapping.Table
import java.time.Instant
import java.time.LocalDate
import java.util.UUID

@Table("movies")
data class Movie(
    // Generated by postgres uuidv7 generator
    @Id val id: UUID? = null,
    val title: String,
    val synopsis: String? = null,
    val releaseDate: LocalDate? = null,
    val runtimeMinutes: Int? = null,
    // Path under media-app's media folder, e.g. "{movieId}/{uuid}.jpg".
    val artworkKey: String? = null,
    @CreatedDate @InsertOnlyProperty val createdAt: Instant = Instant.now(),
    @LastModifiedDate val updatedAt: Instant = Instant.now(),
    @Version val version: Long = 0,
)
